  if (v_host is null and p_type in ('http', 'ssl', 'tcp')) or p_target_host is distinct from v_host then
    raise exception 'host_mismatch' using errcode = 'P0001';
  end if;

  select count(*) into v_count from public.monitors where workspace_id = p_workspace_id and not auto;
  if v_count >= p_max_monitors then
    raise exception 'monitor_limit' using errcode = 'P0001';
  end if;

  if p_type = 'heartbeat' then
    select count(*) into v_count from public.monitors where workspace_id = p_workspace_id and type = 'heartbeat';
    if v_count >= p_max_heartbeats then
      raise exception 'heartbeat_limit' using errcode = 'P0001';
    end if;
  end if;

  v_asserts := case when jsonb_typeof(p_config -> 'assertions') = 'array'
                    then jsonb_array_length(p_config -> 'assertions') else 0 end;
  -- Parenthesised: PL/pgSQL reads an IF condition up to the first THEN, a CASE's included.
  if v_asserts > (case when p_type = 'heartbeat' then p_max_heartbeat_assertions else p_max_assertions end) then
    raise exception 'assertion_limit' using errcode = 'P0001';
  end if;

  if (p_type in ('http', 'tcp') and p_interval_sec < p_min_interval_sec)
     or (p_type = 'dns' and p_interval_sec < 600)
     or (p_type = 'ssl' and p_interval_sec <> 21600) then
    raise exception 'interval_not_allowed' using errcode = 'P0001';
  end if;

  if v_host is not null and p_type <> 'ssl' then
    select count(*) into v_count from public.monitors
     where workspace_id = p_workspace_id and target_host = v_host and type <> 'ssl';
    if v_count >= p_per_host then
      raise exception 'host_limit' using errcode = 'P0001';
    end if;
==SVC
  if not found then raise exception 'not_found' using errcode = 'PT404'; end if;
  if p_edit then
    select * into old from public.monitors where id = p_id and workspace_id = p_workspace_id for update;
    if not found or old.type <> p_type or old.app_id <> p_app_id then raise exception 'not_found' using errcode = 'PT404'; end if;
  else
    if (select count(*) from public.monitors where workspace_id = p_workspace_id and not auto) >= p_max_monitors then raise exception 'monitor_limit'; end if;
    if (select count(*) from public.monitors where workspace_id = p_workspace_id and type = p_type) >= p_max_type then raise exception 'service_monitor_limit'; end if;
  end if;
  if p_name is null or char_length(btrim(p_name)) not between 1 and 80 then raise exception 'service_config_invalid'; end if;
  if p_config is null or jsonb_typeof(p_config) <> 'object' or p_sealed is null
    or p_sealed !~ '^v1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$' then raise exception 'service_config_invalid'; end if;
  if p_type = 'supabase' then
    if p_target is null or p_target !~ '^https://[a-z0-9]{20}\.supabase\.co$'
      or p_config->>'projectUrl' is distinct from p_target
      or jsonb_typeof(p_config->'databaseRead') is distinct from 'string'
      or (p_config->>'databaseRead' <> '' and p_config->>'databaseRead' !~ '^(rpc/)?[a-z_][a-z0-9_]{0,62}$')
      or p_config - array['projectUrl', 'databaseRead'] <> '{}'::jsonb then raise exception 'service_config_invalid'; end if;
    host := substring(p_target from 9);
    if p_interval_sec not in (60, 180) then raise exception 'interval_not_allowed'; end if;
    if (not p_edit or host is distinct from old.target_host) and
      (select count(*) from public.monitors where workspace_id = p_workspace_id and target_host = host and type <> 'ssl' and id <> p_id) >= p_per_host then raise exception 'host_limit'; end if;
==APP
    raise exception 'not_found' using errcode = 'PT404';
  end if;

  -- A workspace past the limit, from before it existed or from a lapsed Builder plan, keeps its
  -- apps: the count only refuses the next one.
  select count(*) into v_count from public.apps where workspace_id = p_workspace_id;
  if v_count >= p_max_apps then
    raise exception 'app_limit' using errcode = 'P0001';
  end if;
==PAGE
  if not found then
    raise exception 'not_found' using errcode = 'PT404';
  end if;

  select count(*) into v_count from public.status_pages where workspace_id = p_workspace_id;
  if v_count >= p_max_pages then
    raise exception 'page_limit' using errcode = 'P0001';
  end if;
==TOKEN

create or replace function public.agent_token_create(p_workspace_id text,p_id text,p_name text,p_kid text,p_hash text,p_scope text)
returns void language plpgsql security invoker set search_path = '' as $fn$
begin
  perform 1 from public.workspaces where id=p_workspace_id for update;
